const body = $json.body || $json;
const p = body.payload || {};
return {
  json: {
    contact_id: body.contact_id,
    email: p.email || body.email || body.contact_id,
    source: p.source || body.source || 'unknown',
    company: p.company || body.company || null,
    phone: p.phone || body.phone || null,
    industry: p.industry || body.industry || null,
    signal_id: body.signal_id || null,
    signal_severity: body.signal_severity || 0,
    session_id: body.session_id
  }
};

const source = $json.source;
const severity = $json.signal_severity || 0;

// Rule-based scoring
const sourceScore = {
  organic: 80,
  referral: 90,
  paid: 60,
  unknown: 40
}[source] || 40;

const severityBoost = Math.round(severity * 20);
const score = Math.min(sourceScore + severityBoost, 100);

const tags = [];
if (score >= 80) tags.push('hot-lead');
else if (score >= 60) tags.push('warm-lead');
else tags.push('cold-lead');

if (source === 'referral') tags.push('referral-source');

return {
  json: {
    ...$json,
    lead_score: score,
    tags
  }
};

try {
  const res = ($json.results || []);
  if (!res.length) throw new Error('no HubSpot results');
  const cid = res[0].id;
  if (!cid) throw new Error('no contact id in HubSpot response');
  const normalized = $('NormalizeLead').item.json;
  return {
    json: {
      contact_id: cid,
      email: normalized.email,
      lead_score: $json.results[0].properties.lead_score || $('ScoreLeadLogic').item.json.lead_score,
      tags: ($json.results[0].properties.xnoria_tags || '').split(',').filter(Boolean) || $('ScoreLeadLogic').item.json.tags,
      session_id: normalized.session_id
    }
  };
} catch (e) {
  const scored = $('ScoreLeadLogic').item.json;
  return {
    json: {
      contact_id: scored.email,
      email: scored.email,
      lead_score: scored.lead_score,
      tags: scored.tags,
      session_id: $('NormalizeLead').item.json.session_id,
      hubspot_error: e.message
    }
  };
}
